const RecordArkFundingSignature = `-- name: RecordArkFundingSignature :execrows
UPDATE ark_channels SET funding_signature = $1,
    revision = revision + 1, updated_at = $2
WHERE channel_id = $3 AND revision = $4
    AND client_node_key = $5 AND phase = 2
    AND authorized_backing_txid = $6 AND funding_signature IS NULL
`

type RecordArkFundingSignatureParams struct {
	Signature []byte
	UpdatedAt int64
	ChannelID []byte
	Revision  int64
	OwnerKey  []byte
	Txid      []byte
}

func (q *Queries) RecordArkFundingSignature(ctx context.Context, arg RecordArkFundingSignatureParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, RecordArkFundingSignature,
		arg.Signature,
		arg.UpdatedAt,
		arg.ChannelID,
		arg.Revision,
		arg.OwnerKey,
		arg.Txid,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
